 "content": "def transform(grid):
    """Propagate the largest non-divider shape through each row of panels,
    recolored with that row's color key in the first panel."""
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    sep_rows = {r for r, row in enumerate(g) if row and row[0] != 0 and all(v == row[0] for v in row)}
    sep_cols = {c for c in range(w) if g[0][c] != 0 and all(g[r][c] == g[0][c] for r in range(h))}
    def spans(n, separators):
        out, start = [], 0
        for i in range(n):
            if i in separators:
                if start < i:
                    out.append((start, i))
                start = i + 1
        if start < n:
            out.append((start, n))
        return out
    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    panels = []
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            pts = [(r-r0, c-c0, g[r][c]) for r in range(r0, r1) for c in range(c0, c1) if g[r][c] != 0]
            panels.append((ri, ci, r0, r1, c0, c1, pts))
    # The template is the panel containing the most non-background cells.
    # Key panels are small solid 2x2 swatches, while the template has more cells.
    template_panel = max(panels, key=lambda p: len(p[6]))
    _, _, tr0, tr1, tc0, tc1, tpts = template_panel
    shape = {(dr, dc) for dr, dc, _ in tpts}
    # Use the first-column swatch in each panel row as its output color.
    output = [[0 for _ in range(w)] for _ in range(h)]
    for r in sep_rows:
        output[r] = list(g[r])
    for c in sep_cols:
        for r in range(h):
            output[r][c] = g[r][c]
    for ri, (r0, r1) in enumerate(rs):
        first = next((p for p in panels if p[0] == ri and p[1] == 0), None)
        if first is None or not first[6]:
            continue
        colors = [v for _, _, v in first[6]]
        color = max(set(colors), key=colors.count)
        for ci, (c0, c1) in enumerate(cs):
            for dr, dc in shape:
                rr, cc = r0 + dr, c0 + dc
                if rr < r1 and cc < c1:
                    output[rr][cc] = color
    return output
